import{_ as h,o as t,c,a2 as o}from"./chunks/framework.62rcL0wY.js";const u=JSON.parse('{"title":"Xử lý lỗi và câu hỏi thường gặp (FAQ)","description":"","frontmatter":{},"headers":[],"relativePath":"xu-ly-loi.md","filePath":"xu-ly-loi.md"}'),a={name:"xu-ly-loi.md"};function i(e,n,g,r,l,m){return t(),c("div",null,[...n[0]||(n[0]=[o('<h1 id="xu-ly-loi-va-cau-hoi-thuong-gap-faq" tabindex="-1">Xử lý lỗi và câu hỏi thường gặp (FAQ) <a class="header-anchor" href="#xu-ly-loi-va-cau-hoi-thuong-gap-faq" aria-label="Permalink to &quot;Xử lý lỗi và câu hỏi thường gặp (FAQ)&quot;">​</a></h1><p>Trang này tổng hợp cách khắc phục nhanh các sự cố thường gặp khi mới làm quen với Clickermann v4.13 cũng như các câu hỏi thường gặp trong tài liệu trợ giúp. <em>(Lưu ý: một số tên nút tiếng Anh như Settings, Record, Open trong bài là tên minh họa để dễ hình dung, vì tài liệu trợ giúp gốc viết bằng tiếng Nga).</em></p><h2 id="script-khong-dung-duoc-con-tro-chuot-tu-chay-lien-tuc" tabindex="-1">Script không dừng được (con trỏ chuột tự chạy liên tục) <a class="header-anchor" href="#script-khong-dung-duoc-con-tro-chuot-tu-chay-lien-tuc" aria-label="Permalink to &quot;Script không dừng được (con trỏ chuột tự chạy liên tục)&quot;">​</a></h2><p>Khi script có lệnh điều khiển chuột (như <code>LCLICK</code>, <code>MOVE</code>, <code>LDOWN</code>) đang chạy lặp liên tục, bạn rất khó dùng chuột để bấm vào nút <strong>Dừng</strong> trên cửa sổ Clickermann.</p><ul><li><strong>Cách xử lý ngay:</strong> Nhấn tổ hợp phím tắt toàn cục <strong><code>Alt + S</code></strong> trên bàn phím để ngắt script ngay lập tức mà không cần chạm vào chuột.</li><li>Nếu vừa dừng giữa chừng một script có lệnh giữ chuột <code>LDOWN</code> và thấy nút chuột trái vẫn đang bị giữ, hãy bấm chuột trái một cái trên vùng trống để nhả ra.</li><li>Nếu nhấn <code>Alt + S</code> không có tác dụng do xung đột phím tắt, hãy xem mục <a href="#phim-tat-alt-a-alt-s-khong-hoat-dong">Phím tắt không hoạt động</a> bên dưới.</li></ul><h2 id="bam-chay-nhung-khong-thay-chuyen-gi-xay-ra" tabindex="-1">Bấm chạy nhưng không thấy chuyện gì xảy ra <a class="header-anchor" href="#bam-chay-nhung-khong-thay-chuyen-gi-xay-ra" aria-label="Permalink to &quot;Bấm chạy nhưng không thấy chuyện gì xảy ra&quot;">​</a></h2><p>Nếu bạn vừa gõ hoặc sửa code xong, bấm Chạy (<code>Alt + A</code>) mà không thấy Clickermann thực hiện lệnh mới:</p><ol><li><strong>Quên bấm nút Áp dụng:</strong> Trong <a href="/clickermann-guide-vi/bat-dau/trinh-soan-thao.html">Trình soạn thảo</a>, sau khi gõ hoặc sửa code, bạn <strong>bắt buộc phải bấm nút Áp dụng</strong> (ở cột bên trái) trước khi bấm Chạy. Nếu chưa bấm Áp dụng, chương trình vẫn chạy kịch bản cũ (hoặc kịch bản trống ban đầu).</li><li><strong>Chưa mở cửa sổ Nhật ký:</strong> Nếu script của bạn chỉ in kết quả bằng lệnh <a href="/clickermann-guide-vi/lenh/nhat-ky.html#logwrite-print"><code>PRINT</code></a> / <code>LOGWRITE</code> mà không di chuyển chuột, hãy bấm nút <strong>Nhật ký</strong> ở cột bên trái của Trình soạn thảo (hoặc gọi <code>LOGSHOW(1)</code> trong script) để mở cửa sổ nhật ký xem kết quả.</li></ol><h2 id="khong-tim-thay-tep-txt-ini-bmp-do-script-tao-ra-hoac-script-khong-doc-duoc-tep" tabindex="-1">Không tìm thấy tệp <code>.txt</code>, <code>.ini</code>, <code>.bmp</code> do script tạo ra (hoặc script không đọc được tệp) <a class="header-anchor" href="#khong-tim-thay-tep-txt-ini-bmp-do-script-tao-ra-hoac-script-khong-doc-duoc-tep" aria-label="Permalink to &quot;Không tìm thấy tệp `.txt`, `.ini`, `.bmp` do script tạo ra (hoặc script không đọc được tệp)&quot;">​</a></h2><ul><li><strong>Nguyên nhân:</strong> Từ bản v4.6.000, mọi đường dẫn tệp tương đối (chỉ viết tên tệp như <code>&quot;cau_hinh.ini&quot;</code>, <code>&quot;nut_bam.bmp&quot;</code>) đều được tính từ <strong>thư mục dự án</strong> — tức là thư mục chứa tệp script <code>.cms</code> đang nạp.</li><li><strong>Cách xử lý:</strong><ul><li>Trước khi chạy script có đọc/ghi tệp, hãy nhấn <code>Ctrl + S</code> trong Trình soạn thảo để lưu tệp <code>.cms</code> vào một thư mục riêng (thư mục dự án), và đặt các tệp <code>.bmp</code>, <code>.txt</code>, <code>.ini</code> cần dùng vào <strong>cùng thư mục với tệp <code>.cms</code> đó</strong>.</li><li>Riêng với lệnh chụp màn hình <a href="/clickermann-guide-vi/lenh/man-hinh.html#screenshot"><code>SCREENSHOT</code></a> và <a href="/clickermann-guide-vi/lenh/man-hinh.html#screenshotex"><code>SCREENSHOTEX</code></a>, ảnh chụp thường được đặt trong thư mục con <code>screens\\</code> nằm bên trong thư mục dự án.</li></ul></li></ul><h2 id="lam-sao-de-vua-chay-clickermann-vua-dung-may-tinh-lam-viec-khac" tabindex="-1">Làm sao để vừa chạy Clickermann vừa dùng máy tính làm việc khác? <a class="header-anchor" href="#lam-sao-de-vua-chay-clickermann-vua-dung-may-tinh-lam-viec-khac" aria-label="Permalink to &quot;Làm sao để vừa chạy Clickermann vừa dùng máy tính làm việc khác?&quot;">​</a></h2><p>Trong một số trường hợp, bạn có thể dùng <strong><a href="/clickermann-guide-vi/khai-niem/khoa-cua-so.html">Chế độ khóa cửa sổ</a></strong> (<code>Alt + W</code> hoặc lệnh <a href="/clickermann-guide-vi/lenh/winapi.html#hset"><code>HSET</code></a>). Ở chế độ này, Clickermann không chiếm chuột và bàn phím thật mà hoạt động ngay cả trong cửa sổ không kích hoạt hoặc đang bị cửa sổ khác che khuất, giúp bạn thoải mái làm việc riêng.</p><p>Trong một số trường hợp, bạn thậm chí có thể dùng các lệnh phân tích hình ảnh (<code>GETSCREEN</code>, <code>IF_PIXEL_IN</code>...) ngay cả khi cửa sổ đó đang bị cửa sổ khác đè lên (miễn là <strong>không thu nhỏ</strong> cửa sổ xuống thanh tác vụ). Tuy nhiên, không phải mọi ứng dụng đều cho phép làm như vậy; khả năng hoạt động của chế độ này phụ thuộc vào ứng dụng đích.</p><h2 id="khong-bam-duoc-chuot-ban-phim-o-che-do-khoa-cua-so" tabindex="-1">Không bấm được chuột / bàn phím ở chế độ khóa cửa sổ <a class="header-anchor" href="#khong-bam-duoc-chuot-ban-phim-o-che-do-khoa-cua-so" aria-label="Permalink to &quot;Không bấm được chuột / bàn phím ở chế độ khóa cửa sổ&quot;">​</a></h2><p>Khi bạn dùng chế độ khóa cửa sổ (<code>Alt + W</code>), có thể phát sinh những trục trặc đặc thù <strong>tùy cách ứng dụng được viết</strong> (ví dụ: trên Firefox chạy được, trên Google Chrome thì không).</p><p><strong>Cách xử lý:</strong></p><ul><li><strong>Suy luận:</strong> Kiểm tra lại xem lúc nhấn <code>Alt + W</code> bạn đã trỏ chuột đúng vào <strong>phần tử con</strong> cần thao tác bên trong cửa sổ chưa (thay vì khóa nhầm vào phần khung/thanh tiêu đề ngoài cùng).</li><li>Nếu ứng dụng đích không hoạt động với chế độ khóa cửa sổ, hãy từ bỏ chế độ khóa cửa sổ để chuyển sang chế độ thường nếu chấp nhận được, hoặc chạy Clickermann ở chế độ thường bên trong một máy ảo (xem <a href="/clickermann-guide-vi/khai-niem/khoa-cua-so.html#gioi-han-va-giai-phap-dung-may-ao">Chế độ khóa cửa sổ</a>).</li><li>Lưu ý: Clickermann có chỉ thị <code>#ps2_mouse</code>, <code>#ps2_keyboard</code> (chế độ PS/2). Tài liệu này không hướng dẫn phần đó.</li></ul><h2 id="cac-lenh-doc-mau-tim-anh-khong-hoat-dong" tabindex="-1">Các lệnh đọc màu / tìm ảnh không hoạt động <a class="header-anchor" href="#cac-lenh-doc-mau-tim-anh-khong-hoat-dong" aria-label="Permalink to &quot;Các lệnh đọc màu / tìm ảnh không hoạt động&quot;">​</a></h2><p>Nếu các lệnh <a href="/clickermann-guide-vi/lenh/man-hinh.html#pxl"><code>PXL</code></a>, <a href="/clickermann-guide-vi/lenh/man-hinh.html#if-pixel-in-end-if"><code>IF_PIXEL_IN</code></a> hay <a href="/clickermann-guide-vi/lenh/man-hinh.html#if-picture-in-end-if"><code>IF_PICTURE_IN</code></a> không hoạt động như mong đợi:</p><ol><li><strong>Quên gọi <code>GETSCREEN</code>:</strong> Đây là lỗi rất thường gặp ở người mới học (&quot;trong trình soạn thảo thì thấy màu mà vào script lại không chạy&quot;). Hãy nhớ đặt lệnh <a href="/clickermann-guide-vi/lenh/man-hinh.html#getscreen"><code>GETSCREEN</code></a> trước các lệnh phân tích màn hình để cập nhật <a href="/clickermann-guide-vi/khai-niem/bo-dem-anh.html">bộ đệm ảnh</a>.</li><li><strong>Lớp phủ (Overlay) và cửa sổ phân lớp / trong suốt:</strong><ul><li>Các <strong>lớp phủ (overlay)</strong> và các <strong>cửa sổ phân lớp (trong suốt)</strong> đều không được chụp vào bộ đệm ảnh.</li><li>Riêng với <strong>cửa sổ trong suốt</strong>, công cụ <strong><a href="/clickermann-guide-vi/bat-dau/quan-ly-cua-so.html">Quản lý cửa sổ</a></strong> có thể xử lý được: nếu bạn đặt độ hiển thị của cửa sổ đó lên <strong>100%</strong> (theo ảnh trong help của bản cũ: chọn <strong>Alpha 100%</strong> rồi bấm nút áp dụng), cờ cửa sổ phân lớp sẽ được gỡ bỏ và Clickermann bắt đầu nhìn thấy cửa sổ đó.</li></ul></li><li><strong>Con trỏ chuột đồ họa riêng:</strong> Nếu ứng dụng sử dụng con trỏ chuột đồ họa riêng, trình soạn thảo có thể lúc nào cũng chỉ nhìn thấy điểm ảnh mang màu của chính con trỏ đồ họa đó. Cách khắc phục: tắt con trỏ đồ họa trong phần cài đặt của ứng dụng (nếu có), hoặc trước khi phân tích hãy dùng <a href="/clickermann-guide-vi/lenh/chuot.html#move"><code>MOVE</code></a> đưa con trỏ chuột ra góc xa rồi mới chụp màn hình và xử lý.</li><li><strong>Cửa sổ đang bị thu nhỏ:</strong> Ở chế độ khóa cửa sổ, nếu cửa sổ bị thu nhỏ xuống thanh tác vụ thì Windows ngừng vẽ cửa sổ đó nên các hàm phân tích đồ họa không hoạt động (màu trong kính lúp luôn là màu đen).</li></ol><h2 id="chuong-trinh-co-ho-tro-nhieu-man-hinh-multi-monitor-khong" tabindex="-1">Chương trình có hỗ trợ nhiều màn hình (Multi-monitor) không? <a class="header-anchor" href="#chuong-trinh-co-ho-tro-nhieu-man-hinh-multi-monitor-khong" aria-label="Permalink to &quot;Chương trình có hỗ trợ nhiều màn hình (Multi-monitor) không?&quot;">​</a></h2><p><strong>Có.</strong> Clickermann hỗ trợ đầy đủ màn hình mở rộng (Extended Desktop / nhiều màn hình) cho cả các lệnh phân tích màn hình lẫn các lệnh bấm chuột, bất kể tọa độ mang giá trị dương hay giá trị âm.</p><h2 id="lam-sao-de-tu-dong-chay-script-ngay-khi-mo-tep-cms" tabindex="-1">Làm sao để tự động chạy script ngay khi mở tệp <code>.cms</code>? <a class="header-anchor" href="#lam-sao-de-tu-dong-chay-script-ngay-khi-mo-tep-cms" aria-label="Permalink to &quot;Làm sao để tự động chạy script ngay khi mở tệp `.cms`?&quot;">​</a></h2><p>Thực hiện 2 bước sau:</p><ol><li>Thêm chỉ thị <code>#autorun</code> vào script <code>.cms</code>.</li><li>Mở phần cài đặt (Settings) của Clickermann và tạo liên kết định dạng tệp <code>*.cms</code> (File Association) với Clickermann.</li></ol><p>Từ lúc đó, khi bạn mở tệp <code>.cms</code> (giống như mở tệp <code>.txt</code> bằng Notepad), Clickermann sẽ khởi động và bắt đầu chạy ngay script đó. Lưu ý: tự động chạy không áp dụng khi bạn mở script từ bên trong cửa sổ chương trình ngay cả khi có chỉ thị <code>#autorun</code>.</p><h2 id="phim-tat-alt-a-alt-s-khong-hoat-dong" tabindex="-1">Phím tắt (<code>Alt + A</code>, <code>Alt + S</code>...) không hoạt động <a class="header-anchor" href="#phim-tat-alt-a-alt-s-khong-hoat-dong" aria-label="Permalink to &quot;Phím tắt (`Alt + A`, `Alt + S`...) không hoạt động&quot;">​</a></h2><p>Có thể sau khi mở Clickermann, một chương trình khác đã gán đè tổ hợp phím tắt đó cho riêng nó.</p><ul><li>Hãy vào phần cài đặt của Clickermann, đặt lại các phím tắt cần thiết, bấm áp dụng và khởi động lại chương trình. Nếu vẫn còn xung đột, hãy thử các tổ hợp phím khác.</li><li>Nếu bạn dùng cùng lúc nhiều bản Clickermann nhân bản, bạn cần đặt cho mỗi bản một bộ phím tắt riêng.</li></ul><h2 id="script-ghi-tu-dong-record-qua-dai-vi-toan-lenh-move" tabindex="-1">Script ghi tự động (Record) quá dài vì toàn lệnh <code>MOVE</code> <a class="header-anchor" href="#script-ghi-tu-dong-record-qua-dai-vi-toan-lenh-move" aria-label="Permalink to &quot;Script ghi tự động (Record) quá dài vì toàn lệnh `MOVE`&quot;">​</a></h2><p>Khi bạn ghi lại thao tác (Record), script tạo ra có thể rất dài và toàn là lệnh <a href="/clickermann-guide-vi/lenh/chuot.html#move"><code>MOVE</code></a> gây bất tiện khi chỉnh sửa.</p><p><strong>Cách xử lý:</strong> Trước khi ghi, hãy vào phần cài đặt (Settings) và <strong>bỏ dấu chọn ở mục &quot;ghi lại chuyển động chuột&quot;</strong> (minh họa tiếng Anh: <em>Record mouse movements</em>).</p><h2 id="chuong-trinh-ket-noi-mang-khi-vua-khoi-dong" tabindex="-1">Chương trình kết nối mạng khi vừa khởi động <a class="header-anchor" href="#chuong-trinh-ket-noi-mang-khi-vua-khoi-dong" aria-label="Permalink to &quot;Chương trình kết nối mạng khi vừa khởi động&quot;">​</a></h2><p>Khi vừa mở lên, Clickermann tự động kiểm tra bản cập nhật mới trên máy chủ chính thức. Bạn có thể tắt chức năng này trong phần cài đặt. Ngoài ra, tường lửa cũng có thể cảnh báo nếu bản thân script đang chạy có <strong>sử dụng các hàm mạng</strong>.</p><h2 id="phan-mem-diet-virus-canh-bao" tabindex="-1">Phần mềm diệt virus cảnh báo <a class="header-anchor" href="#phan-mem-diet-virus-canh-bao" aria-label="Permalink to &quot;Phần mềm diệt virus cảnh báo&quot;">​</a></h2><p>Trình diệt virus (thường là các trình diệt virus ít tên tuổi, không phổ biến) có thể không thích khả năng theo dõi chuột, bàn phím và các chức năng tương tự của chương trình. Nếu bạn tải đúng bản chính thức từ <code>http://crapware.aidf.org</code>, hãy thêm Clickermann vào danh sách loại trừ (exclusion) của trình diệt virus.</p><hr><p><em>Nguồn: Tài liệu trợ giúp <code>help.chm</code> (phần FAQ, bài Khóa cửa sổ, bài Trình soạn thảo và Lịch sử phiên bản).</em></p>',38)])])}const s=h(a,[["render",i]]);export{u as __pageData,s as default};
